create table blog_post_tags (blog_post_id bigint not null, tag_id bigint not null, primary key (blog_post_id, tag_id));
create table blog_posts (created_at timestamp(6) not null, id bigint generated by default as identity, user_id bigint not null, content TEXT not null, status varchar(255) not null check ((status in ('PUBLISHED','ARCHIVED'))), title varchar(255) not null, primary key (id));
create table forum_categories (id bigint generated by default as identity, description varchar(255), name varchar(255) not null, primary key (id));
create table forum_posts (author_id bigint not null, created_at timestamp(6) not null, id bigint generated by default as identity, parent_post bigint, thread_id bigint not null, content varchar(255) not null, primary key (id));
create table forum_threads (locked boolean not null, pinned boolean not null, author_id bigint not null, category_id bigint, created_at timestamp(6) not null, id bigint generated by default as identity, content varchar(255) not null, title varchar(255) not null, primary key (id));
create table listing_images (is_primary boolean not null, id bigint generated by default as identity, listing_id bigint not null, image_path varchar(255) not null, primary key (id));
create table listings (price integer, created_at timestamp(6) not null, id bigint generated by default as identity, user_id bigint not null, description varchar(500), contact_email varchar(255), contact_number varchar(255), status varchar(255) not null check ((status in ('ACTIVE','ARCHIVED'))), title varchar(255) not null, primary key (id));
create table tags (id bigint generated by default as identity, name varchar(255) not null, primary key (id));
create table users (created_at timestamp(6) not null, id bigint generated by default as identity, bio varchar(255), email varchar(255) not null unique, password_hash varchar(255) not null, role varchar(255) not null check ((role in ('USER','VETERAN','MODERATOR','ADMIN'))), username varchar(255) not null unique, primary key (id));
alter table if exists blog_post_tags add constraint FK7r354i1e3pr00mu7y5fpx17mn foreign key (tag_id) references tags;
alter table if exists blog_post_tags add constraint FK9lwi4pg2kl7ce7pa3r3yotb9w foreign key (blog_post_id) references blog_posts;
alter table if exists blog_posts add constraint FK9bebj0jhg2mqq7ei9tsy3iwly foreign key (user_id) references users;
alter table if exists forum_posts add constraint FKpsovhjndrj3obmt1d0p9nhr0u foreign key (author_id) references users;
alter table if exists forum_posts add constraint FKnv87oof4368rg9wj9g8s6na3s foreign key (parent_post) references forum_posts;
alter table if exists forum_posts add constraint FKf21wc9cbq41u82bmu9uiic1mj foreign key (thread_id) references forum_threads;
alter table if exists forum_threads add constraint FKkqxyyup50bgueyp87s7vfy93b foreign key (author_id) references users;
alter table if exists forum_threads add constraint FK6a6l88dmbm3oit8kalfflu7ll foreign key (category_id) references forum_categories;
alter table if exists listing_images add constraint FKq8bkplrutxrfur5u7pppml04y foreign key (listing_id) references listings;
alter table if exists listings add constraint FKb5kgkbggc40jyxeq28onih2x1 foreign key (user_id) references users;
